class Solution:
    def minimizedStringLength(self, s: str) -> int:
        return len(set(s)))

class Solution:
    def flowerGame(self, n: int, m: int) -> int:
        even_x = n // 2
        odd_x = n - even_x

        even_y = m // 2
        odd_y = m - even_y

        return (even_x * odd_y) + (odd_x * even_y))

class Solution:
    def sumOfTheDigitsOfHarshadNumber(self, x: int) -> int:
        sum_digits = sum(int(d) for d in str(x)))
        if x % sum_digits == 0:
            return sum_digits
        else:
            return -1

from typing import List

class Solution:
    def occurrencesOfElement(self, nums: List[int], queries: List[int], x: int) -> List[int]:
        positions = []
        for i, num in enumerate(nums):
            if num == x:
                positions.append(i)
        res = []
        for q in queries:
            if q <= len(positions):
                res.append(positions[q-1]]))
            else:
                res.append(-1)
        return res

